selected.compute:
options = read('/input/options')
valid_existing = False
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
        valid_existing = True
if not valid_existing:
    result = []
    for n in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(options, n):
            ids = [record['id'] for record in group]
            if valid(ids):
                result = ids
                break
        if len(result) > 0:
            break

selected.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
